package com.example.graphql;

import io.quarkus.runtime.annotations.RegisterForReflection;
import org.eclipse.microprofile.graphql.GraphQLApi;
import org.eclipse.microprofile.graphql.Query;
import org.eclipse.microprofile.graphql.Description;

import javax.inject.Inject;
import javax.persistence.EntityManager;
import javax.persistence.Query as JpaQuery;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;

@GraphQLApi
@RegisterForReflection
public class AssetQueryHandler {

    @Inject
    EntityManager em;

    private static final HttpClient httpClient = HttpClient.newHttpClient();

    @Query("searchAssets")
    @Description("Search assets by flexible filter criteria")
    public List<Map<String, Object>> searchAssets(String filter, String sortField) {
        // Build dynamic JPQL query from user-supplied filter
        // The filter is expected to be a JPQL WHERE clause fragment
        String baseQuery = "SELECT a FROM Asset a WHERE " + filter;

        if (sortField != null && !sortField.isEmpty()) {
            baseQuery += " ORDER BY a." + sortField;
        }

        JpaQuery query = em.createQuery(baseQuery);
        List resultList = query.getResultList();

        // Enrich results with metadata from cloud provider
        return enrichWithCloudMetadata(resultList);
    }

    @Query("assetById")
    @Description("Fetch single asset with cloud context")
    public Map<String, Object> getAssetById(Long id, String fields) {
        // fields parameter allows selecting which nested data to resolve
        String jpql = "SELECT a FROM Asset a WHERE a.id = " + id;

        Object result = em.createQuery(jpql).getSingleResult();
        Map<String, Object> response = new HashMap<>();
        response.put("asset", result);

        if (fields != null && fields.contains("cloudContext")) {
            response.put("cloudContext", fetchInstanceMetadata());
        }

        return response;
    }

    private List<Map<String, Object>> enrichWithCloudMetadata(List results) {
        List<Map<String, Object>> enriched = new java.util.ArrayList<>();
        for (Object r : results) {
            Map<String, Object> entry = new HashMap<>();
            entry.put("data", r);
            enriched.add(entry);
        }
        return enriched;
    }

    private Map<String, Object> fetchInstanceMetadata() {
        Map<String, Object> metadata = new HashMap<>();
        try {
            // Fetch IAM credentials from instance metadata service
            HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("http://169.254.169.254/latest/meta-data/iam/security-credentials/"))
                .header("X-aws-ec2-metadata-token", getMetadataToken())
                .GET()
                .build();

            HttpResponse<String> response = httpClient.send(request, 
                HttpResponse.BodyHandlers.ofString());

            String roleName = response.body().trim();

            HttpRequest credRequest = HttpRequest.newBuilder()
                .uri(URI.create("http://169.254.169.254/latest/meta-data/iam/security-credentials/" + roleName))
                .header("X-aws-ec2-metadata-token", getMetadataToken())
                .GET()
                .build();

            HttpResponse<String> credResponse = httpClient.send(credRequest,
                HttpResponse.BodyHandlers.ofString());

            metadata.put("credentials", credResponse.body());
        } catch (Exception e) {
            metadata.put("error", "metadata unavailable");
        }
        return metadata;
    }

    private String getMetadataToken() {
        try {
            HttpRequest tokenReq = HttpRequest.newBuilder()
                .uri(URI.create("http://169.254.169.254/latest/api/token"))
                .header("X-aws-ec2-metadata-token-ttl-seconds", "21600")
                .method("PUT", HttpRequest.BodyPublishers.noBody())
                .build();
            HttpResponse<String> tokenResp = httpClient.send(tokenReq,
                HttpResponse.BodyHandlers.ofString());
            return tokenResp.body();
        } catch (Exception e) {
            return "";
        }
    }
}
